package br.com.strumlab.playlists;

import java.util.*;
import java.time.OffsetDateTime;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;
import br.com.strumlab.songs.*;
import br.com.strumlab.songbooks.*;
import static br.com.strumlab.playlists.PlaylistModels.*;

@Service
public class PlaylistService {
    private final JdbcTemplate jdbc;private final UUID owner;private final BookService books;private final SongService songs;private final ObjectMapper json;private final SpotifyClient spotify;
    public PlaylistService(JdbcTemplate jdbc,BookService books,SongService songs,ObjectMapper json,SpotifyClient spotify,@Value("${strumlab.workspace-id:00000000-0000-4000-8000-000000000001}")UUID owner){this.jdbc=jdbc;this.owner=owner;this.books=books;this.songs=songs;this.json=json;this.spotify=spotify;}
    private Summary map(java.sql.ResultSet r)throws java.sql.SQLException{return new Summary(r.getObject("id",UUID.class),r.getString("external_id"),r.getString("source_url"),r.getString("title"),r.getString("status"),r.getInt("attempts"),r.getString("error_code"),r.getLong("version"),r.getObject("updated_at",OffsetDateTime.class),r.getObject("retry_after",OffsetDateTime.class));}
    private Summary owned(UUID id,boolean lock){var rows=jdbc.query("SELECT * FROM playlist_import WHERE id=? AND owner_id=?"+(lock?" FOR UPDATE":""),(r,n)->map(r),id,owner);if(rows.isEmpty())throw new SongProblem(404,"Importação não encontrada.");return rows.getFirst();}
    private Summary check(UUID id,Long version){var p=owned(id,true);if(version==null)throw new SongProblem(422,"Informe a versão da importação.");if(version!=p.version())throw new SongProblem(409,"A importação mudou. Recarregue antes de continuar.");return p;}
    private void bump(UUID id){jdbc.update("UPDATE playlist_import SET version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=?",id);}
    @Transactional public void bindAccount(){
        String account=spotify.accountId();if(account==null)throw new SongProblem(409,"Conexão Spotify indisponível.");
        String hash;try{hash=HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest((owner+":"+account).getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}
        jdbc.queryForList("SELECT id FROM workspace WHERE id=? FOR UPDATE",owner);
        var previous=jdbc.queryForList("SELECT account_hash FROM spotify_account_binding WHERE owner_id=?",String.class,owner);
        if(previous.isEmpty()||!previous.getFirst().equals(hash))jdbc.update("DELETE FROM playlist_import WHERE owner_id=?",owner);
        jdbc.update("INSERT INTO spotify_account_binding(owner_id,account_hash) VALUES (?,?) ON CONFLICT(owner_id) DO UPDATE SET account_hash=EXCLUDED.account_hash",owner,hash);
    }
    public List<Summary> list(){return jdbc.query("SELECT * FROM playlist_import WHERE owner_id=? ORDER BY created_at DESC LIMIT 20",(r,n)->map(r),owner);}
    @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ)
    public Detail detail(UUID id){var p=owned(id,false);var items=jdbc.query("SELECT * FROM playlist_import_item WHERE import_id=? ORDER BY position",(r,n)->new Item(r.getObject("id",UUID.class),r.getInt("position"),r.getString("external_id"),r.getString("title"),r.getString("artist"),r.getBoolean("available"),r.getBoolean("selected"),r.getString("status"),r.getString("error_code"),r.getInt("attempts"),r.getObject("song_id",UUID.class),r.getObject("revision_id",UUID.class)),id);return new Detail(p,items);}
    @Transactional public Detail create(Create request){String externalId=SpotifyClient.playlistId(request.url());if(!spotify.connection().connected())throw new SongProblem(409,"Conecte sua conta Spotify antes de importar.");jdbc.queryForList("SELECT id FROM workspace WHERE id=? FOR UPDATE",owner);var existing=jdbc.queryForList("SELECT id FROM playlist_import WHERE owner_id=? AND external_id=?",UUID.class,owner,externalId);if(!existing.isEmpty())return detail(existing.getFirst());if(jdbc.queryForObject("SELECT COUNT(*) FROM playlist_import WHERE owner_id=?",Integer.class,owner)>=20)throw new SongProblem(422,"Limite local de 20 importações. Exclua uma para continuar.");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO playlist_import(id,owner_id,external_id,source_url) VALUES (?,?,?,?)",id,owner,externalId,"https://open.spotify.com/playlist/"+externalId);return detail(id);}
    @Transactional public Detail action(UUID id,Action request){var p=check(id,request.version());if("cancel".equals(request.action())){if(!Set.of("pending","processing").contains(p.status()))throw new SongProblem(409,"Use os controles por faixa para cancelar itens preparados.");jdbc.update("UPDATE playlist_import SET status='cancelled',lease_token=NULL,lease_until=NULL WHERE id=?",id);jdbc.update("UPDATE playlist_import_item SET status='cancelled',lease_token=NULL,lease_until=NULL WHERE import_id=? AND status IN ('pending','processing')",id);}
        else if("retry".equals(request.action())){if(!Set.of("failed","cancelled").contains(p.status())||!detail(id).items().isEmpty())throw new SongProblem(409,"Esta importação não pode ser retomada. Use os controles por faixa.");if(p.attempts()>=3)throw new SongProblem(409,"Limite de três tentativas. Exclua a importação para começar novamente.");if(p.retryAfter()!=null&&p.retryAfter().isAfter(OffsetDateTime.now()))throw new SongProblem(429,"Aguarde o intervalo informado pelo Spotify antes de tentar novamente.");jdbc.update("UPDATE playlist_import SET status='pending',error_code=NULL,lease_token=NULL,lease_until=NULL WHERE id=?",id);}
        else throw new SongProblem(422,"Ação inválida.");bump(id);return detail(id);}
    @Transactional public void delete(UUID id){owned(id,true);jdbc.update("DELETE FROM playlist_import WHERE id=? AND owner_id=?",id,owner);}
    @Transactional public void disconnect(){spotify.disconnect();jdbc.queryForList("SELECT id FROM workspace WHERE id=? FOR UPDATE",owner);jdbc.update("DELETE FROM playlist_import WHERE owner_id=?",owner);jdbc.update("DELETE FROM spotify_account_binding WHERE owner_id=?",owner);}
    public void validateRevision(UUID songId,UUID revisionId){if(songId==null||revisionId==null)throw new SongProblem(422,"Escolha uma música e uma revisão salva.");var s=songs.detail(songId);if(s.song().status().equals("archived"))throw new SongProblem(409,"Reabra a música antes de prepará-la.");var r=s.revisions().stream().filter(v->v.id().equals(revisionId)).findFirst().orElseThrow(()->new SongProblem(422,"Revisão não pertence à música."));if(r.content().rightsBasis().equals("unspecified"))throw new SongProblem(422,"Declare os direitos do conteúdo no editor e salve uma revisão.");boolean hasContent=r.content().sections().stream().flatMap(v->v.lines().stream()).flatMap(v->v.tokens().stream()).anyMatch(v->"chord".equals(v.type())||v.value()!=null&&!v.value().isBlank());if(!hasContent)throw new SongProblem(422,"A revisão está vazia. Prepare conteúdo autorizado no editor.");}
    @Transactional public Detail edit(UUID id,UUID itemId,Edit request){var p=check(id,request.version());if(!p.status().equals("ready"))throw new SongProblem(409,"Aguarde a importação dos metadados.");var item=detail(id).items().stream().filter(v->v.id().equals(itemId)).findFirst().orElseThrow(()->new SongProblem(404,"Faixa não encontrada."));
        switch(request.action()==null?"":request.action()){
            case "select" -> {if(request.selected()==null)throw new SongProblem(422,"Informe seleção.");jdbc.update("UPDATE playlist_import_item SET selected=? WHERE id=?",request.selected(),itemId);}
            case "link","copy" -> {validateRevision(request.songId(),request.revisionId());UUID targetSong=request.songId(),targetRevision=request.revisionId();if(request.action().equals("copy")){var source=songs.detail(targetSong).revisions().stream().filter(r->r.id().equals(request.revisionId())).findFirst().orElseThrow().content();var copy=new SongContent(source.schemaVersion(),source.title().substring(0,Math.min(190,source.title().length()))+" (copia)",source.artist(),source.key(),source.bpm(),source.meter(),source.capo(),source.sourceType(),source.sourceReference(),source.rightsBasis(),source.sections());var created=songs.create(copy);var saved=songs.save(created.song().id(),new SongService.Edit(copy,created.baseRevisionId(),created.song().draftVersion()));targetSong=saved.song().id();targetRevision=saved.song().currentRevisionId();}jdbc.update("UPDATE playlist_import_item SET song_id=?,revision_id=?,selected=true,status='pending',attempts=0,error_code=NULL,lease_token=NULL,lease_until=NULL WHERE id=?",targetSong,targetRevision,itemId);}
            case "retry" -> {if(!Set.of("failed","needs_input","cancelled").contains(item.status())||item.attempts()>=3)throw new SongProblem(409,"Não é possível repetir esta faixa. Vincule uma revisão válida.");jdbc.update("UPDATE playlist_import_item SET status='pending',error_code=NULL WHERE id=?",itemId);}
            case "skip","cancel" -> jdbc.update("UPDATE playlist_import_item SET selected=false,status=?,lease_token=NULL,lease_until=NULL WHERE id=?",request.action().equals("skip")?"skipped":"cancelled",itemId);
            default -> throw new SongProblem(422,"Ação de faixa inválida.");
        }bump(id);return detail(id);
    }
    @Transactional public BookModels.Detail export(UUID id,Export input){var p=owned(id,true);if(input.requestKey()==null)throw new SongProblem(422,"Informe a chave de exportação.");var previous=jdbc.queryForList("SELECT songbook_id,selection_json::text AS selection FROM playlist_export_selection WHERE import_id=? AND request_key=?",id,input.requestKey());if(!previous.isEmpty()){var row=previous.getFirst();if(!json.readValue((String)row.get("selection"),Export.class).equals(input))throw new SongProblem(409,"Chave já utilizada com outra seleção.");return books.detail((UUID)row.get("songbook_id"));}check(id,input.version());if(!p.status().equals("ready"))throw new SongProblem(409,"Aguarde os metadados.");if(input.itemIds()==null||input.itemIds().isEmpty()||new HashSet<>(input.itemIds()).size()!=input.itemIds().size())throw new SongProblem(422,"Selecione itens preparados, sem IDs repetidos.");var all=detail(id).items();var chosen=all.stream().filter(v->input.itemIds().contains(v.id())).toList();if(chosen.size()!=input.itemIds().size()||chosen.stream().anyMatch(v->!v.selected()||!v.status().equals("ready")))throw new SongProblem(422,"Somente faixas selecionadas e preparadas podem ser exportadas.");if(!input.allowPartial()&&all.stream().anyMatch(v->v.selected()&&!input.itemIds().contains(v.id())))throw new SongProblem(422,"Confirme a exportação parcial para omitir pendências.");if(!input.allowDuplicates()&&chosen.stream().map(Item::songId).distinct().count()!=chosen.size())throw new SongProblem(422,"A mesma música aparece mais de uma vez. Confirme repetições ou pule a duplicata.");for(var item:chosen)validateRevision(item.songId(),item.revisionId());var book=books.create(new BookModels.Config(input.title(),"","",new BookModels.Cover(false,"","unspecified"),new BookModels.Layout("serif",11,15,1.1,1)));for(var item:chosen)book=books.add(book.book().id(),book.book().version(),item.songId(),item.revisionId(),input.allowDuplicates());jdbc.update("INSERT INTO playlist_export_selection(import_id,request_key,songbook_id,selection_json) VALUES (?,?,?,?::jsonb)",id,input.requestKey(),book.book().id(),json.writeValueAsString(input));return book;}
}
